-- query: Anomalies ISL 3 Cruise
-- type:  SELECT
-- source: CalCOFI_4903-2304_Master_Final_through_2105_October162023.accdb (ACE12), extracted via Jackcess

SELECT [Anomalies ISL 1 Station].Year, Avg([Anomalies ISL 1 Station].YearValue) AS YearValue, [Anomalies ISL 1 Station].Cruise, [Anomalies ISL 1 Station].Depth, Avg([Anomalies ISL 1 Station].Temp) AS Temp, Avg([Anomalies ISL 1 Station].Sal) AS Sal, Avg([Anomalies ISL 1 Station].Density) AS Density, Avg([Anomalies ISL 1 Station].O2) AS O2, Avg([Anomalies ISL 1 Station].NO3) AS NO3, Avg([Anomalies ISL 1 Station].PO4) AS PO4, Avg([Anomalies ISL 1 Station].SiO3) AS SiO3, Avg([Anomalies ISL 1 Station].O2Sat) AS O2Sat, Avg([Anomalies ISL 1 Station].TempAnom) AS TempAnom, Avg([Anomalies ISL 1 Station].SalAnom) AS SalAnom, Avg([Anomalies ISL 1 Station].DensAnom) AS DensAnom, Avg([Anomalies ISL 1 Station].O2Anom) AS O2Anom, Avg([Anomalies ISL 1 Station].O2SatAnom) AS O2SatAnom, Avg([Anomalies ISL 1 Station].NO3Anom) AS NO3Anom, Avg([Anomalies ISL 1 Station].PO4Anom) AS PO4Anom, Avg([Anomalies ISL 1 Station].SIO3Anom) AS SIO3Anom, Avg([Anomalies ISL 1 Station].TempStAnom) AS TempStAnom, Avg([Anomalies ISL 1 Station].SalStAnom) AS SalStAnom, Avg([Anomalies ISL 1 Station].DensStAnom) AS DensStAnom, Avg([Anomalies ISL 1 Station].O2StAnom) AS O2StAnom, Avg([Anomalies ISL 1 Station].O2SatStAnom) AS O2SatStAnom, Avg([Anomalies ISL 1 Station].NO3StAnom) AS NO3StAnom, Avg([Anomalies ISL 1 Station].PO4StAnom) AS PO4StAnom, Avg([Anomalies ISL 1 Station].SIO3StAnom) AS SIO3StAnom
FROM St_Stations INNER JOIN [Anomalies ISL 1 Station] ON St_Stations.Sta_ID = [Anomalies ISL 1 Station].Sta_ID
GROUP BY [Anomalies ISL 1 Station].Year, [Anomalies ISL 1 Station].Cruise, [Anomalies ISL 1 Station].Depth
ORDER BY [Anomalies ISL 1 Station].Cruise;
